SELECT a.discharge_location, a.discharge_facility, a.deathtime, percent_of_los_within_10_days, AVG(a.los) AS average_los, PERCENTILE_CONT(0.25) WITHIN GROUP (ORDER BY a.los) AS percentile_025, PERCENTILE_CONT(0.50) WITHIN GROUP (ORDER BY a.los) AS percentile_050, PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY a.los) AS percentile_075, PERCENTILE_CONT(0.90) WITHIN GROUP (ORDER BY a.los) AS percentile_090 FROM admissions a JOIN patients p ON a.subject_id = p.subject_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) BETWEEN 59 AND 69 AND a.admission_type = 'M' AND a.discharge_time IS NOT NULL AND a.deathtime IS NOT NULL AND percent_of_los_within_10_days <= 10 GROUP BY a.discharge_location, a.discharge_facility, a.deathtime, percent_of_los_within_10_days ORDER BY a.discharge_location, a.discharge_facility, a.deathtime, percent_of_los_within_10_days NULLS LAST;